          "သို့သော် ဘုရားရှင်သည် မည်သည့်အခါမျှ တုန်လှုပ်ခြင်း၊ ကြောက်ရွံ့ခြင်း မရှိဘဲ တည်ငြိမ်စွာပင် ရှိနေသည်",
