          "မကောင်းသော စိတ်ထားရှိသူပင်လျှင် ဘုရားရှင်၏ ဂုဏ်ကျေးဇူးကြောင့် ပြောင်းလဲသွားနိုင်ခြင်း",
          "ဤဝတ္ထုသည် မည်သူမဆို ဘုရားရှင်၏ ဂုဏ်တော်ကို ကြည်ညိုပါက ကောင်းကျိုးချမ်းသာ ရရှိနိုင်ကြောင်း သွန်သင်ဆုံးမထားသော ဝတ္ထုတစ်ရပ်ဖြစ်ပေသည်",
