          "ယင်းသည် အကြီးမားဆုံး ဓာတ်ငွေ့ဂြိုဟ်နှင့် ဂြိုဟ်ရံလများ၏အသေးစိတ်ဓာတ်ပုံများကို ဖမ်းယူနိုင်ခဲ့သော အာကာသယာဉ် ဖြစ်လာခဲ့သည်",
          "ဒီအန်အေကို သက်ရှိများ၏ ကလာပ်စည်းတိုင်းတွင် တွေ့ရှိရပြီး ယင်းကလာပ်စည်းအား မည်သို့သော ပရိုတိန်းကို ထုတ်လုပ်ရမည်ဟု ညွှန်ကြားသည်",
          "ထို့ကြောင့် ရင်သွေးများသည် မိဘများနှင့် အသားအရောင်၊ ဆံပင်အရောင်၊ မျက်လုံးအရောင် စသည့် ရုပ်အင်္ဂါအားဖြင့် ဆင်တူကြခြင်းဖြစ်သည်",
          "မြတ်စွာဘုရားသခင်အား သားဟု ခေါ်ဝေါ်ကာ အိမ်သို့ ပင့်ဆောင်သွားသော သာကေတမြို့နေ ပုဏ္ဏားလင်မယားအကြောင်း",
          "စစ်ကိုင်းနရပတိစည်သူကို စလင်းကို စားရ၍ စလင်းစည်သူကျော်ထင်၊ နောက်ပိုင်း စစ်ကိုင်းကို စားရ၍ စစ်ကိုင်းစည်သူကျော်ထင်ဟုလည်း ခေါ်ကြသေးသည်",
          "အင်းဝမင်းဆက်၏ နောက်ဆုံးမင်းဖြစ်သည့် အမည်ရင်း စည်သူကျော်ထင် ရှိသော နရပတိစည်သူသည် တိုက်ရည်ခိုက်ရည်ကောင်းသည့် သူရဲကောင်းတစ်ဦးဖြစ်သည်",
