          "၎င်းသည် ပတ်ဝန်းကျင်နိုင်ငံများတွင် တူညီမှုမရှိသော ထူးခြားသောအမည်ဖြစ်ပြီး ၎င်း၏ဇာစ်မြစ်ကို ရှင်းရှင်းလင်းလင်း မသိရပေ",
