          "လူဇင်ဘတ်ဘုရင် ဂျွန် လက်ထက်တွင် မြို့တော်ကို ဩစတြီးယား မြို့စားကြီးများထံ အကြိမ်ကြိမ် ကတိပြုခဲ့သည်",
          "ကော်လင်သတ္တုသိုက်များကို ရှာဖွေတွေ့ရှိခြင်းသည် မြို့တော်ရှိ ကြွေထည်လုပ်ငန်းကို ဖွံ့ဖြိုးတိုးတက်စေခဲ့သည်",
          "နောက်ပိုင်းတွင် နာမည်ကြီး အနုပညာရှင်များသည် ပြည်တွင်းကြွေထည်ကျောင်းသို့ တက်ရောက်ခဲ့ကြပါသည်",
          "ပြင်သစ်စာရေးဆရာကြီး အေမီးဇိုလာ၏ဖခင်မှာ အီတာလျံ လူမျိုး အင်ဂျင်နီယာ ဖရန်ဆွာဖိုလာဖြစ်၍၊ မိခင်မှာ ပြင်သစ်လူမျိုးဖြစ်သည်",
          "နှစ်နှစ်မျှ စာရေးအလုပ်ဖြင့် အသက်ဝမ်းကျောင်းပြီးလျှင် ထိုအလုပ်ကို စွန့်လွှတ်လိုက်ပြီးသော်၊ စာရေးဆရာလုပ်ရန် ဆုံးဖြတ်လိုက်၏",
          "နောက်တစ်နှစ်တွင် ဒေါသ၏အကြောင်းကို သရုပ်ဖော်၍ ဝတ္ထုတစ်ပုဒ် ရေးသားရာ၊ ထိုဝတ္ထုတအုပ်နှင့်ပင် နာမည်ထင်ရှားလာခဲ့လေသည်",
          "အေမီ ဇိုလာသည် စိတ်ကူးယဉ်ဝတ္ထုရေးဆရာမဟုတ်ဘဲ၊ အဖြစ်သနစ်အမှန်သဘာဝကို မထောက်မညှာ ဖော်ပြတတ်သော သူဖြစ်၏",
          "ထိုကိစ္စတွင် မတရားမှုကိုမရှုနိုင်သော ဇိုလာသည် ပြင်သစ်စစ်ဖက်အရာရှိများကို သတင်းစာမှ နေ၍အတိုက်အခံ ရေးသားခဲ့၏",
          "ဒရေးဖပ်အမှုကို ထပ်မံစစ်ဆေးသောအခါ၊ တရားခံအပေါ်တွင် အပြစ်မရှိကြောင်း ထင်ရှားလာ လေသည်",
          "ဇိုလာသည် လူ့လောက၏ ယုတ်မာဆိုးသွမ်း ပုံတို့ကို သရုပ်ဖော်တတ်သဖြင့် စိတ်ကူးယဉ်စွာ ရေးထားသော အချစ်ဇာတ်လမ်းများနှင့် တစ်ဘက်တစ်လမ်း ကွာခြားလေသည်",
          "ထိုတရားသုံးပါးတို့ လောက၌ ထင်ရှားကုန်သောကြောင့် အရဟံဂုဏ်ရှင် သမ္မာသမ္ဗုဒ္ဓဂုဏ်ရှင်ဖြစ်တော်မူသော ဘုရားရှင် လောက၌ ဖြစ်ပွင့်တော်မူ၏",
