          "-လီနစိတ္တပုဂ္ဂိုလ်ဖြစ်လျှင် သက္ကာယဒိဋ္ဌိ၊ ဝိစိကိစ္ဆာ၊ သီလဗ္ဗတပရာမာသကို မပယ် မစွန့်နိုင်",
          "အရောင်အသွေးမှာ နှစ်မျိုးနှစ်စားဖြစ်ပြီး အခြေအနေအလိုက် အညိုရောင် ရှိရာမှ အပြာရောင်သို့ ပြောင်းနိုင်သည်",
