          "မြန်မာ့ရေနံနှင့် သဘာဝဓာတ်ငွေ့လုပ်ငန်းအားဖြင့် စွမ်းအင်တူးဖော်ခြင်း၊ ဖြန့်ချိခြင်း ထုတ်လုပ်ခြင်းတို့ကို ဆောင်ရွက်လျက်ရှိသည်",
          "မက်ဂနိစ်ဒိုင်အောက်ဆိုဒ်ကို သွပ်ကာဗွန်နှင့် အယ်ကာလိုင်း ဘက်ထရီများတွင် ကတ်သုပ်အဖြစ် အသုံးပြုသည်",
          "အချို့သော မဂ္ဂနိ ဓာတ်ဆားများကို ဓာတုဗေဒတွင် လည်းကောင်း၊ ဘယဆေးများ ဖော်စပ်ရာတွင် လည်းကောင်း အသုံးပြုရ၏",
